<script setup lang="ts">
import { computed,reactive,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElButton,ElCheckbox,ElCheckboxGroup,ElInput,ElMessage,ElOption,ElSelect } from 'element-plus'
import { money,useCommerceStore } from '@/stores/commerce'
const c=useCommerceStore(),router=useRouter(),route=useRoute();const kind=ref<'customer'|'platform'>('customer');const park=ref('');const chosen=ref<string[]>(route.query.order?[String(route.query.order)]:[]);const form=reactive({number:'',file:'',title:'',email:'',subjectType:'企业',ticketType:'增值税普通发票',taxId:'',address:'',phone:'',bank:'',account:''});const eligible=computed(()=>c.data.orders.filter(o=>kind.value==='customer'?o.paid>0&&!c.activeRefund(o.id)&&c.invoiceable(o)>0:o.settlement==='settled'&&!c.data.invoices.some(i=>i.kind==='platform'&&i.orderIds.includes(o.id)&&['issuing','issued','returning'].includes(i.status))).filter(o=>!park.value||o.parkId===park.value));const total=computed(()=>eligible.value.filter(o=>chosen.value.includes(o.id)).reduce((n,o)=>n+(kind.value==='customer'?c.invoiceable(o):(o.paid-o.refunded)*o.shareRate/100),0))
function setKind(v:'customer'|'platform'){kind.value=v;chosen.value=[];park.value='';Object.assign(form,{number:'',file:'',title:'',email:'',subjectType:'企业',ticketType:'增值税普通发票',taxId:'',address:'',phone:'',bank:'',account:''})}
function pick(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!['application/pdf','image/png','image/jpeg'].includes(f.type)){ElMessage.error('仅支持 PDF、JPG、PNG');return}form.file=f.name}
function submit(){if(!chosen.value.length){ElMessage.warning('请选择订单');return}if(kind.value==='customer'&&(!form.number.trim()||!form.file)){ElMessage.warning('请填写发票号码并上传发票文件');return}if(kind.value==='platform'&&(!form.title.trim()||!form.taxId.trim()||!form.address.trim()||!form.phone.trim()||!form.bank.trim()||!form.account.trim()||!/^\S+@\S+\.\S+$/.test(form.email))){ElMessage.warning('请完整填写抬头、税号、地址、电话、开户行、账号和邮箱');return}if(!c.issueInvoice(kind.value,chosen.value,form.number,form.file,form.title,form.email,form)){ElMessage.error('订单状态或合并规则不满足开票条件');return}ElMessage.success(kind.value==='customer'?'对客发票已记录':'平台发票申请已提交');router.push('/invoice/record')}
</script><template><div class="biz-page"><header class="biz-head"><div><h1>开票申请</h1><p>按开票类型选择符合条件的订单。</p></div></header><div v-if="!c.data.walletOpen" class="biz-empty"><h3>开通钱包后申请开票</h3><ElButton type="primary" @click="router.push('/wallet')">前往我的钱包</ElButton></div><template v-else><div class="biz-tabs"><button class="biz-tab" :class="{active:kind==='customer'}" @click="setKind('customer')">对客开票</button><button class="biz-tab" :class="{active:kind==='platform'}" @click="setKind('platform')">平台服务费发票</button></div><p class="biz-note">{{kind==='customer'?'已支付且无进行中退款的订单可申请对客开票，可跨园区合并。':'仅已结算订单可申请平台服务费发票，合并时必须属于同一园区。'}}</p><section class="biz-section"><div class="biz-inline"><h2 style="margin:0">选择订单</h2><ElSelect v-if="kind==='platform'" v-model="park" clearable placeholder="选择园区以合并" style="width:240px" @change="chosen=[]"><ElOption v-for="p in c.joinedParks" :key="p.id" :label="p.name" :value="p.id"/></ElSelect></div><div v-if="!eligible.length" class="biz-empty"><h3>暂无可开票订单</h3><p>订单满足支付、退款和结算条件后会出现在这里。</p></div><ElCheckboxGroup v-else v-model="chosen" class="invoice-orders"><ElCheckbox v-for="o in eligible" :key="o.id" :value="o.id" :disabled="kind==='platform'&&chosen.length>0&&c.data.orders.find(x=>x.id===chosen[0])?.parkId!==o.parkId"><span><strong>{{o.id}}</strong> · {{o.serviceName}} · {{money(kind==='customer'?c.invoiceable(o):(o.paid-o.refunded)*o.shareRate/100)}}</span></ElCheckbox></ElCheckboxGroup><p class="biz-muted">已选 {{chosen.length}} 笔，合计 <strong>{{money(total)}}</strong></p></section><section class="biz-section"><h2>{{kind==='customer'?'上传对客发票':'填写平台开票信息'}}</h2><div class="biz-grid"><template v-if="kind==='customer'"><label class="biz-field">发票号码 <b class="required">*</b><ElInput v-model="form.number"/></label><label class="biz-field">发票文件 <b class="required">*</b><input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="pick"/><small>{{form.file||'PDF / JPG / PNG'}}</small></label></template><template v-else><label class="biz-field">发票抬头 <b class="required">*</b><ElInput v-model="form.title"/></label><label class="biz-field">接收邮箱 <b class="required">*</b><ElInput v-model="form.email"/></label><label class="biz-field">主体类型 <ElSelect v-model="form.subjectType"><ElOption label="企业" value="企业"/></ElSelect></label><label class="biz-field">发票类型 <ElSelect v-model="form.ticketType"><ElOption label="增值税普通发票" value="增值税普通发票"/><ElOption label="增值税专用发票" value="增值税专用发票"/></ElSelect></label><label class="biz-field">纳税人识别号 <b class="required">*</b><ElInput v-model="form.taxId"/></label><label class="biz-field">联系地址 <b class="required">*</b><ElInput v-model="form.address"/></label><label class="biz-field">联系电话 <b class="required">*</b><ElInput v-model="form.phone"/></label><label class="biz-field">开户银行 <b class="required">*</b><ElInput v-model="form.bank"/></label><label class="biz-field">银行账号 <b class="required">*</b><ElInput v-model="form.account"/></label></template></div></section><div class="biz-footer"><span class="biz-muted">提交后可在开票记录查看状态。</span><ElButton type="primary" @click="submit">{{kind==='customer'?'确认开票':'提交申请'}}</ElButton></div></template></div></template><style scoped>.invoice-orders{display:grid;gap:10px;margin:18px 0}.invoice-orders :deep(.el-checkbox){padding:12px 14px;border:1px solid #e2e9f2;border-radius:8px;margin:0}</style>
